-- Phase 3: listening sessions
--
-- A session is an append-only log of events (start, pause, next, flip…) written
-- by the browser. What played when is DERIVED from that log and the tracklist
-- snapshot, then stored in session_plays for history, stats and (Phase 4)
-- scrobbling.
--
-- * listening_sessions  one per listen; holds a frozen copy of the tracklist
--                       ("program") so editing the copy later can't rewrite history
-- * session_events      the log; ids are generated by the browser so retried
--                       uploads are idempotent
-- * session_plays       derived plays, one row per track occurrence

create table public.listening_sessions (
  id                uuid primary key,  -- generated by the browser
  owner_id          uuid not null default auth.uid() references auth.users (id) on delete cascade,
  physical_copy_id  uuid references public.physical_copies (id) on delete set null,
  album_id          uuid references public.albums (id) on delete set null,
  format            public.media_format not null,
  program           jsonb not null check (jsonb_typeof(program) = 'object'),
  status            text not null check (status in ('playing', 'paused', 'side_done', 'album_done', 'ended')),
  started_at        timestamptz not null,
  ended_at          timestamptz,
  last_event_at     timestamptz not null,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  check ((status = 'ended') = (ended_at is not null)),
  check (ended_at is null or ended_at >= started_at),
  check (last_event_at >= started_at)
);

-- At most one unfinished session per user: a second scan or double-tapped
-- Start can never create a parallel session.
create unique index listening_sessions_one_active
  on public.listening_sessions (owner_id) where status <> 'ended';
create index listening_sessions_owner_started_idx on public.listening_sessions (owner_id, started_at desc);
create index listening_sessions_copy_idx on public.listening_sessions (physical_copy_id);
create index listening_sessions_album_idx on public.listening_sessions (album_id);

create trigger listening_sessions_updated_at before update on public.listening_sessions
  for each row execute function public.set_updated_at();

create table public.session_events (
  id          uuid primary key,  -- generated by the browser
  owner_id    uuid not null default auth.uid() references auth.users (id) on delete cascade,
  session_id  uuid not null references public.listening_sessions (id) on delete cascade,
  at          timestamptz not null,
  type        text not null check (type in ('start', 'pause', 'resume', 'next', 'previous', 'skip', 'restart',
                                            'select', 'correct', 'startSide', 'confirm', 'end')),
  payload     jsonb not null default '{}'::jsonb check (jsonb_typeof(payload) = 'object'),
  created_at  timestamptz not null default now()
);

create index session_events_session_at_idx on public.session_events (session_id, at);
create index session_events_owner_idx on public.session_events (owner_id);

create table public.session_plays (
  session_id        uuid not null references public.listening_sessions (id) on delete cascade,
  seq               integer not null check (seq between 0 and 9999),
  owner_id          uuid not null default auth.uid() references auth.users (id) on delete cascade,
  -- Tracks survive tracklist edits, so this link is stable. Snapshot columns
  -- below keep history readable even if the track is later deleted.
  track_id          uuid references public.tracks (id) on delete set null,
  side_label        text not null,
  track_position    smallint not null check (track_position >= 1),
  title             text not null,
  artist            text not null,
  album_title       text not null,
  album_artist      text not null,
  duration_seconds  integer not null check (duration_seconds > 0),
  started_at        timestamptz not null,
  ended_at          timestamptz not null,
  listened_seconds  integer not null check (listened_seconds >= 0),
  end_reason        text not null check (end_reason in ('completed', 'next', 'previous', 'skipped', 'restarted', 'selected', 'ended')),
  -- Meets Last.fm's rules: track > 30 s, heard ≥ half or ≥ 4 min, not skipped/restarted.
  counts            boolean not null,
  -- No longer revisable (e.g. not waiting on "did you hear the whole side?").
  final             boolean not null,
  updated_at        timestamptz not null default now(),
  primary key (session_id, seq),
  check (ended_at >= started_at)
);

create index session_plays_owner_started_idx on public.session_plays (owner_id, started_at desc);
create index session_plays_track_idx on public.session_plays (track_id);

create trigger session_plays_updated_at before update on public.session_plays
  for each row execute function public.set_updated_at();

alter table public.listening_sessions enable row level security;
alter table public.session_events     enable row level security;
alter table public.session_plays      enable row level security;

create policy "owner can do everything" on public.listening_sessions
  for all to authenticated
  using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy "owner can do everything" on public.session_events
  for all to authenticated
  using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy "owner can do everything" on public.session_plays
  for all to authenticated
  using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));

revoke all on public.listening_sessions, public.session_events, public.session_plays from anon;

-- ---------------------------------------------------------------------------
-- Owner consistency. RLS checks each row's own owner_id, but foreign-key checks
-- ignore RLS, so without these a user could attach rows to another user's
-- album/copy/session just by knowing its id. Each child now references its
-- parent by (id, owner_id), so parent and child must have the same owner.
-- ---------------------------------------------------------------------------
alter table public.albums             add constraint albums_id_owner_key unique (id, owner_id);
alter table public.physical_copies    add constraint physical_copies_id_owner_key unique (id, owner_id);
alter table public.tracks             add constraint tracks_id_owner_key unique (id, owner_id);
alter table public.listening_sessions add constraint listening_sessions_id_owner_key unique (id, owner_id);

alter table public.physical_copies add constraint physical_copies_album_owner_fkey
  foreign key (album_id, owner_id) references public.albums (id, owner_id) on delete cascade;
alter table public.tracks add constraint tracks_album_owner_fkey
  foreign key (album_id, owner_id) references public.albums (id, owner_id) on delete cascade;
alter table public.copy_sides add constraint copy_sides_copy_owner_fkey
  foreign key (physical_copy_id, owner_id) references public.physical_copies (id, owner_id) on delete cascade;
-- copy_tracks: one FK to its copy covering album AND owner (replaces the
-- (copy, album) FK). Its side (same copy) and track (same album) then share
-- that owner through the other composite FKs.
alter table public.physical_copies add constraint physical_copies_id_album_owner_key unique (id, album_id, owner_id);
alter table public.copy_tracks add constraint copy_tracks_copy_album_owner_fkey
  foreign key (physical_copy_id, album_id, owner_id) references public.physical_copies (id, album_id, owner_id) on delete cascade;

-- "set null (col)" clears only the link column, never owner_id.
alter table public.listening_sessions add constraint listening_sessions_copy_owner_fkey
  foreign key (physical_copy_id, owner_id) references public.physical_copies (id, owner_id) on delete set null (physical_copy_id);
alter table public.listening_sessions add constraint listening_sessions_album_owner_fkey
  foreign key (album_id, owner_id) references public.albums (id, owner_id) on delete set null (album_id);
alter table public.session_events add constraint session_events_session_owner_fkey
  foreign key (session_id, owner_id) references public.listening_sessions (id, owner_id) on delete cascade;
alter table public.session_plays add constraint session_plays_session_owner_fkey
  foreign key (session_id, owner_id) references public.listening_sessions (id, owner_id) on delete cascade;
alter table public.session_plays add constraint session_plays_track_owner_fkey
  foreign key (track_id, owner_id) references public.tracks (id, owner_id) on delete set null (track_id);

-- The owner-aware FKs above make the original single-column ones redundant.
-- Dropping them also matters for the Supabase API: PostgREST refuses nested
-- selects (albums → physical_copies …) when two FKs link the same tables.
alter table public.physical_copies    drop constraint physical_copies_album_id_fkey;
alter table public.tracks             drop constraint tracks_album_id_fkey;
alter table public.copy_sides         drop constraint copy_sides_physical_copy_id_fkey;
alter table public.copy_tracks        drop constraint copy_tracks_physical_copy_id_album_id_fkey;
alter table public.listening_sessions drop constraint listening_sessions_physical_copy_id_fkey;
alter table public.listening_sessions drop constraint listening_sessions_album_id_fkey;
alter table public.session_events     drop constraint session_events_session_id_fkey;
alter table public.session_plays      drop constraint session_plays_session_id_fkey;
alter table public.session_plays      drop constraint session_plays_track_id_fkey;

-- ---------------------------------------------------------------------------
-- Played tracks must never be deleted by tracklist cleanup. Same functions as
-- in the library migration, with one extra NOT EXISTS on session_plays.
-- ---------------------------------------------------------------------------
create or replace function public.save_physical_copy(p jsonb) returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_uid        uuid := auth.uid();
  v_album      jsonb := coalesce(p -> 'album', '{}'::jsonb);
  v_copy       jsonb := coalesce(p -> 'copy', '{}'::jsonb);
  v_sides      jsonb := coalesce(p -> 'sides', '[]'::jsonb);
  v_album_id   uuid;
  v_copy_id    uuid := nullif(p ->> 'copy_id', '')::uuid;
  v_rg_id      uuid := nullif(v_album ->> 'musicbrainz_release_group_id', '')::uuid;
  v_side       jsonb;
  v_side_pos   int := 0;
  v_side_id    uuid;
  v_track      jsonb;
  v_track_pos  int;
  v_track_id   uuid;
  v_rec_id     uuid;
  v_duration   int;
  v_existing   public.tracks%rowtype;
  v_override   int;
  v_total      int := 0;
begin
  if v_uid is null then
    raise exception 'Not signed in' using errcode = '28000';
  end if;
  if jsonb_typeof(v_sides) <> 'array' then
    raise exception 'sides must be an array' using errcode = '22023';
  end if;
  if jsonb_array_length(v_sides) > 52 then
    raise exception 'Too many sides (max 52)' using errcode = '22023';
  end if;

  -- 1. Resolve the album -----------------------------------------------------
  if v_copy_id is not null then
    select album_id into v_album_id from public.physical_copies where id = v_copy_id;
    if v_album_id is null then
      raise exception 'Copy % not found', v_copy_id using errcode = 'P0002';
    end if;
  elsif nullif(v_album ->> 'id', '') is not null then
    select id into v_album_id from public.albums where id = (v_album ->> 'id')::uuid;
    if v_album_id is null then
      raise exception 'Album % not found', v_album ->> 'id' using errcode = 'P0002';
    end if;
  else
    if v_rg_id is not null then
      select id into v_album_id from public.albums
        where owner_id = v_uid and musicbrainz_release_group_id = v_rg_id;
    end if;
    if v_album_id is null then
      insert into public.albums (title, artist, album_artist, release_year, artwork_url,
                                 musicbrainz_release_group_id, musicbrainz_artist_id)
      values (
        btrim(v_album ->> 'title'),
        btrim(v_album ->> 'artist'),
        nullif(btrim(v_album ->> 'album_artist'), ''),
        nullif(v_album ->> 'release_year', '')::smallint,
        nullif(v_album ->> 'artwork_url', ''),
        v_rg_id,
        nullif(v_album ->> 'musicbrainz_artist_id', '')::uuid
      )
      returning id into v_album_id;
    end if;
  end if;

  -- 2. Create or update the copy --------------------------------------------
  if v_copy_id is null then
    insert into public.physical_copies (album_id, format) values (v_album_id, (v_copy ->> 'format')::public.media_format)
      returning id into v_copy_id;
  end if;

  update public.physical_copies set
    format                 = (v_copy ->> 'format')::public.media_format,
    edition_name           = nullif(btrim(v_copy ->> 'edition_name'), ''),
    label                  = nullif(btrim(v_copy ->> 'label'), ''),
    catalog_number         = nullif(btrim(v_copy ->> 'catalog_number'), ''),
    barcode                = nullif(btrim(v_copy ->> 'barcode'), ''),
    release_country        = nullif(btrim(v_copy ->> 'release_country'), ''),
    release_year           = nullif(v_copy ->> 'release_year', '')::smallint,
    artwork_url            = nullif(v_copy ->> 'artwork_url', ''),
    musicbrainz_release_id = nullif(v_copy ->> 'musicbrainz_release_id', '')::uuid,
    notes                  = nullif(btrim(v_copy ->> 'notes'), '')
  where id = v_copy_id;

  -- 3. Replace the tracklist -------------------------------------------------
  delete from public.copy_sides where physical_copy_id = v_copy_id;  -- cascades to copy_tracks

  for v_side in select value from jsonb_array_elements(v_sides) loop
    v_side_pos := v_side_pos + 1;
    insert into public.copy_sides (physical_copy_id, position, label)
      values (v_copy_id, v_side_pos, btrim(v_side ->> 'label'))
      returning id into v_side_id;

    v_track_pos := 0;
    for v_track in select value from jsonb_array_elements(coalesce(v_side -> 'tracks', '[]'::jsonb)) loop
      v_track_pos := v_track_pos + 1;
      v_total := v_total + 1;
      if v_total > 400 then
        raise exception 'Too many tracks (max 400)' using errcode = '22023';
      end if;

      v_track_id := nullif(v_track ->> 'track_id', '')::uuid;
      v_rec_id   := nullif(v_track ->> 'musicbrainz_recording_id', '')::uuid;
      v_duration := nullif(v_track ->> 'duration_seconds', '')::int;
      v_override := null;

      -- Reuse an existing album track by id, or by MusicBrainz recording.
      v_existing := null;
      if v_track_id is not null then
        select * into v_existing from public.tracks where id = v_track_id and album_id = v_album_id;
        if v_existing.id is null then
          raise exception 'Track % does not belong to this album', v_track_id using errcode = '22023';
        end if;
      elsif v_rec_id is not null then
        select * into v_existing from public.tracks where album_id = v_album_id and musicbrainz_recording_id = v_rec_id;
      end if;

      if v_existing.id is null then
        insert into public.tracks (album_id, title, artist, duration_seconds, musicbrainz_recording_id)
          values (v_album_id, btrim(v_track ->> 'title'), btrim(v_track ->> 'artist'), v_duration, v_rec_id)
          returning id into v_track_id;
      else
        v_track_id := v_existing.id;
        if v_duration is not null
           and v_existing.duration_seconds is not null
           and v_duration <> v_existing.duration_seconds
           and exists (select 1 from public.copy_tracks
                       where track_id = v_track_id and physical_copy_id <> v_copy_id) then
          -- Another copy relies on the shared duration: keep it, override here.
          v_override := v_duration;
          v_duration := v_existing.duration_seconds;
        end if;
        update public.tracks set
          title            = btrim(v_track ->> 'title'),
          artist           = btrim(v_track ->> 'artist'),
          duration_seconds = coalesce(v_duration, duration_seconds)
        where id = v_track_id;
      end if;

      insert into public.copy_tracks (physical_copy_id, album_id, side_id, track_id, position,
                                      display_number, duration_override)
        values (v_copy_id, v_album_id, v_side_id, v_track_id, v_track_pos,
                nullif(btrim(v_track ->> 'display_number'), ''), v_override);
    end loop;
  end loop;

  -- 4. Remove album tracks that no copy uses AND that were never played.
  delete from public.tracks t
  where t.album_id = v_album_id
    and not exists (select 1 from public.copy_tracks ct where ct.track_id = t.id)
    and not exists (select 1 from public.session_plays sp where sp.track_id = t.id);

  return v_copy_id;
end;
$$;

create or replace function public.delete_physical_copy(p_copy_id uuid) returns boolean
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_album_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Not signed in' using errcode = '28000';
  end if;

  delete from public.physical_copies where id = p_copy_id returning album_id into v_album_id;
  if v_album_id is null then
    raise exception 'Copy % not found', p_copy_id using errcode = 'P0002';
  end if;

  if not exists (select 1 from public.physical_copies where album_id = v_album_id) then
    delete from public.albums where id = v_album_id;
    return true;
  end if;

  delete from public.tracks t
  where t.album_id = v_album_id
    and not exists (select 1 from public.copy_tracks ct where ct.track_id = t.id)
    and not exists (select 1 from public.session_plays sp where sp.track_id = t.id);
  return false;
end;
$$;
